        sum: Optional['types.WardSumAggregateInput'] = None,
        min: Optional['types.WardMinAggregateInput'] = None,
        max: Optional['types.WardMaxAggregateInput'] = None,
        having: Optional['types.WardScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.WardCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.WardScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.WardScalarFieldKeys', 'types.SortOrder']]]] = None,
